newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def carrot(a):return I('carrot',a,'g','carrots, peeled and trimmed','Use the same weight of a different carrot variety; color and sweetness will change.')
def butter(a):return I('butter',a,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.')
def stock(a):return I('stock',a,'ml','unsalted prepared beef stock','Use the same volume of unsalted vegetable stock for a different flavor; check other ingredients before treating the whole recipe as vegetarian.')
def onion(a):return I('onion',a,'g','peeled onion','Use the same weight of trimmed leek, rinsing away any grit.')
def salt(a=3):return I('salt',a,'g','fine salt','Reduce or omit, especially if using salted stock.')
def pepper():return I('pepper',.25,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def cayenne():return I('cayenne',.125,'tsp','ground cayenne pepper','Omit for a milder soup.')
def sugar(a):return I('sugar',a,'g','granulated sugar','Omit for a less sweet soup.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water; water for dough or starch slurry should remain cold.')
def flour(a):return I('flour',a,'g','all-purpose flour','For a sauce, use the same weight of a gluten-free blend labeled for sauces; pastry requires a separate tested gluten-free dough.')
def bread(a):return I('bread',a,'g','plain bread','Use the same weight of gluten-free bread suitable for toasting.')
def oil(a,k='oil'):return I(k,a,'ml','neutral vegetable oil','Use the same volume of refined sunflower or rapeseed oil.')
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g pasteurized liquid yolk per large yolk; omitting yolk changes the recipe.')
def cream(a):return I('cream',a,'ml','heavy cream','Use the same volume of unsweetened plant cream suitable for cooking.')
def celery(a):return I('celery',a,'g','trimmed celery stalks','Use the same weight of peeled celeriac, cut small and cooked until tender.')
def turnip(a):return I('turnip',a,'g','peeled turnip','Use the same weight of peeled rutabaga; allow extra cooking time until tender.')
def add(n,title,y,t,desc,items,steps,notes,category='Side dishes'):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category=category,servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T18:00:00Z',notes=notes+' Missing amounts, yields and timings are modern adaptation estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes quantities, not cooking times. Cool leftovers promptly in shallow containers and refrigerate within 2 hours at 4°C (40°F) or colder.',source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
PUREE='Press the vegetables and their liquid through a coarse sieve into a clean saucepan, or use an immersion blender directly in the deep pan with its head submerged. Do not seal hot soup in a countertop blender.'
def parsley(a=5):return I('parsley',a,'g','fresh parsley, finely chopped','Use the same weight of chives, or omit.')
def milk(a):return I('milk',a,'ml','whole milk','Use the same volume of unsweetened soy milk; flavor differs.')
def rice(a):return I('rice',a,'g','uncooked long-grain white rice','Use the same weight of another white rice; follow its cooking time until tender.')
def eggfinish():return ['Whisk {{yolks}} with {{cream}} in a bowl. Gradually whisk in a little hot soup, then return the mixture to the saucepan.','Stir over low heat until the soup reaches 71°C (160°F), without boiling. Serve promptly.']
