def boilstep(shape='1 cm pieces',minutes='12–18'):
 return 'Cut {{carrot}} into '+shape+'. Bring {{water}} and {{salt}} to a boil, add the carrots and simmer for '+minutes+' minutes until tender when pierced. Drain well.'
def milkversion(r,key='milk',label='Cream instead of milk'):
 variant(r,'cream',label,[dict(i,name='heavy cream',substitution='Use the same volume of whole milk for a lighter result.') if i['key']==key else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))
r=add(35,'Cenouras Ensopadas in White Wine',4,45,'Tender carrot slices are coated in a lightly thickened white-wine sauce.',[carrot(500),water(1000),salt(3),butter(14),flour(8),I('wine',480,'ml','dry white wine','For an alcohol-free variation use 460 ml unsalted vegetable stock plus 20 ml lemon juice.'),pepper()],[boilstep('1 cm rounds'),'Melt {{butter}} in a saucepan, stir in {{flour}} and cook for 2 minutes without browning. Gradually whisk in {{wine}} until smooth.','Add the drained carrots and {{pepper}}. Simmer gently for 10–15 minutes until the sauce lightly coats the carrots.'],'Two equivalent same-book transcriptions are consolidated; the fuller one supplies the butter and flour spoon amounts. Two cups wine becomes a modern 480 ml. Wine remains alcoholic after cooking.')
r=add(40,'Cenouras Refogadas with Scallion Greens',4,35,'Sliced carrots braise with butter and scallion greens in a lightly thickened sauce.',[carrot(500),butter(25),flour(8),I('scallion',15,'g','scallion green tops, sliced','Use the same weight of chives, added near the end.'),water(240),salt(2),pepper()],['Slice {{carrot}} into 5 mm rounds. Melt {{butter}} in a saucepan, add the carrots and {{scallion}}, and cook for 3 minutes, stirring.','Sprinkle over {{flour}}, stir for 1 minute, then gradually add {{water}}, {{salt}} and {{pepper}}.','Cover and simmer gently for 15–25 minutes until tender, stirring occasionally. Add a little water if the sauce begins to catch. Serve with the coating sauce.'],'The missing carrot and butter amounts are supplied. Onion leaves are interpreted as scallion greens; a source cup becomes 240 ml.')
r=add(41,'Cenouras Refogadas com Nata (Cream-Braised Carrots)',4,40,'Carrots braise with parsley and finish in a rich cream sauce thickened with egg yolks.',[carrot(500),butter(15),water(150),salt(2),parsley(),cream(240),yolks(2)],['Slice {{carrot}} into 5 mm rounds. Melt {{butter}} in a saucepan, add the carrots, {{water}}, {{salt}} and {{parsley}}, cover and simmer for 15–25 minutes until tender.','Stir in {{cream|0.9375}} and heat gently until steaming.','Whisk {{yolks}} with {{cream|0.0625}} in a bowl. Gradually whisk in some hot sauce, then return to the carrots. Stir gently over low heat until the sauce reaches 71°C (160°F), without boiling, and serve.'],'The source cream spoon used to mix the yolks is reserved from the 240 ml total, not counted twice. Carrot, butter and water quantities are supplied, with controlled egg heating.')
r=add(46,'Carottes au Beurre with Nutmeg',6,35,'Thin carrot rounds are briefly boiled, then warmed in butter with nutmeg and herbs.',[carrot(800),water(1500),salt(4),butter(60),pepper(),I('nutmeg',.125,'tsp','ground nutmeg','Omit if unavailable.'),water(30,'finishwater'),parsley()],['Slice {{carrot}} into 3 mm rounds. Bring {{water}}, {{salt}} and {{butter|0.25}} to a boil. Add the carrots and simmer for 6–10 minutes until just tender but still firm. Drain.','Melt {{butter|0.75}} in a wide saucepan. Add the carrots, {{pepper}} and {{nutmeg}} and toss over low heat for 2 minutes.','Add {{finishwater}} and {{parsley}}, toss until glossy and hot without letting the butter brown, and serve.'],'Ten to twelve small carrots become 800 g. The source water option is selected instead of the incomplete velouté cross-reference; butter for boiling and finishing is separately apportioned. Fine herbs are represented by parsley, with chives as a substitution.')
r=add(58,'Stewed Carrot Strips with Milk',4,40,'Boiled carrot strips are finished in a milk sauce thickened with flour mixed into butter.',[carrot(500),water(1000),salt(4),butter(28),flour(16),milk(240),pepper()],[boilstep('5 cm long, 1 cm thick strips','15–20'),'Mash softened {{butter}} with {{flour}} to make a smooth paste. Put the drained carrots back in the saucepan with {{milk}} and {{pepper}}.','Bring to a gentle simmer. Add the butter-flour paste in small pieces, stirring gently until incorporated. Simmer for 5–7 minutes to cook the flour and coat the carrots.'],'Equivalent Manila and Whitehouse methods are consolidated. Missing carrot, flour and milk amounts are supplied. The Whitehouse cream option is retained as a named version.');milkversion(r)
r=add(59,'Möhrrüben with Parsley Roux',4,35,'Carrot strips cook in lightly sweetened water and are finished with a small parsley roux.',[carrot(500),water(750),salt(5),sugar(5),I('fat',20,'g','block margarine','Use the same weight of unsalted butter.'),flour(10),parsley(2)],['Cut {{carrot}} into even 1 cm thick strips. Bring {{water}}, {{salt}} and {{sugar}} to a boil, add the carrots and simmer covered for 15–25 minutes until tender.','Lift out the carrots, reserving all the cooking liquid. Melt {{fat}} in a small saucepan, stir in {{flour}} and cook for 2 minutes.','Whisk in a ladleful of the reserved carrot liquid until smooth, then stir this mixture into the remaining hot cooking liquid. Simmer for 3–5 minutes, add the carrots and {{parsley}}, and heat through. Serve with the light sauce.'],'Source metric quantities are retained. The roux is first loosened with some cooking liquid, then combined with the rest; no duplicate broth ingredient is added. This is a light sauce because the source water-to-flour ratio is retained.')
r=add(60,'Carrots, Green Beans and Potatoes with Bacon',2,35,'Tender diced vegetables are tossed with browned bacon and vinegar for a simple savory side.',[carrot(125),I('beans',125,'g','trimmed green beans','Use the same weight of trimmed yellow wax beans.'),I('potato',250,'g','peeled potatoes','Use the same weight of another firm cooking potato.'),water(1000),salt(5),I('bacon',15,'g','lean bacon, diced','Use 15 g smoked tofu plus 5 ml oil; fry until lightly browned.'),I('vinegar',15,'ml','cider vinegar','Use the same volume of white wine vinegar.'),pepper()],['Dice {{carrot}} and {{potato}} into 1.5 cm pieces. Cut {{beans}} into 2 cm lengths. Bring {{water}} and {{salt}} to a boil.','Add the carrots and potatoes, simmer for 5 minutes, then add the beans and cook for 10–15 minutes until all vegetables are tender. Drain well.','Meanwhile, cook {{bacon}} in a skillet over medium heat for 5–8 minutes until cooked and lightly crisp. Toss the drained vegetables with the bacon and its rendered fat, {{vinegar}} and {{pepper}}. Serve hot.'],'Source vegetable weights and water are retained; the bacon spoon becomes 15 g and vinegar spoon 15 ml. Staggering the vegetables is a modern adjustment for even tenderness.')
